using AshkanCRM.Models;using Microsoft.EntityFrameworkCore;
namespace AshkanCRM.Data;
public static class CrmDataBootstrapper {
 public static async Task SeedAsync(IServiceProvider services){
  using var scope=services.CreateScope(); var db=scope.ServiceProvider.GetRequiredService<CrmDbContext>();
  // EnsureCreated is retained for a fresh install. For an existing Identity-only database,
  // create the new CRM tables without deleting user/security data.
  await db.Database.EnsureCreatedAsync();
  await db.Database.ExecuteSqlRawAsync("""
IF OBJECT_ID(N'[CrmCustomers]', N'U') IS NULL CREATE TABLE [CrmCustomers]([Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY,[Name] nvarchar(120) NOT NULL,[Company] nvarchar(160) NOT NULL,[Email] nvarchar(180) NOT NULL,[Phone] nvarchar(40) NOT NULL,[Segment] nvarchar(60) NOT NULL,[Owner] nvarchar(160) NOT NULL,[Status] nvarchar(60) NOT NULL,[Score] int NOT NULL,[CreatedAtUtc] datetime2 NOT NULL,[UpdatedAtUtc] datetime2 NOT NULL,[IsDeleted] bit NOT NULL,[CreatedBy] nvarchar(max) NULL,[UpdatedBy] nvarchar(max) NULL,[RowVersion] rowversion NULL);
IF OBJECT_ID(N'[CrmLeads]', N'U') IS NULL CREATE TABLE [CrmLeads]([Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY,[Name] nvarchar(120) NOT NULL,[Company] nvarchar(160) NOT NULL,[Source] nvarchar(80) NOT NULL,[Owner] nvarchar(160) NOT NULL,[Status] nvarchar(60) NOT NULL,[Score] int NOT NULL,[LastContact] nvarchar(80) NOT NULL,[CreatedAtUtc] datetime2 NOT NULL,[UpdatedAtUtc] datetime2 NOT NULL,[IsDeleted] bit NOT NULL,[CreatedBy] nvarchar(max) NULL,[UpdatedBy] nvarchar(max) NULL);
