IF OBJECT_ID(N'[CrmNotifications]', N'U') IS NULL CREATE TABLE [CrmNotifications]([Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY,[UserName] nvarchar(180) NOT NULL,[Type] nvarchar(80) NOT NULL,[Title] nvarchar(240) NOT NULL,[Message] nvarchar(1000) NOT NULL,[IsRead] bit NOT NULL,[ReadAtUtc] datetime2 NULL,[CreatedAtUtc] datetime2 NOT NULL,[UpdatedAtUtc] datetime2 NOT NULL,[IsDeleted] bit NOT NULL,[CreatedBy] nvarchar(max) NULL,[UpdatedBy] nvarchar(max) NULL);
IF OBJECT_ID(N'[CrmTasks]', N'U') IS NULL CREATE TABLE [CrmTasks]([Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY,[Title] nvarchar(240) NOT NULL,[Type] nvarchar(80) NOT NULL,[Assignee] nvarchar(180) NOT NULL,[Priority] nvarchar(40) NOT NULL,[Status] nvarchar(40) NOT NULL,[DueAtUtc] datetime2 NOT NULL,[ReminderAtUtc] datetime2 NULL,[RelatedEntityType] nvarchar(40) NOT NULL,[RelatedEntityId] int NULL,[Description] nvarchar(1200) NOT NULL,[CreatedAtUtc] datetime2 NOT NULL,[UpdatedAtUtc] datetime2 NOT NULL,[IsDeleted] bit NOT NULL,[CreatedBy] nvarchar(max) NULL,[UpdatedBy] nvarchar(max) NULL);
