IF COL_LENGTH('CrmCustomers','TeamKey') IS NULL ALTER TABLE [CrmCustomers] ADD [TeamKey] nvarchar(80) NOT NULL CONSTRAINT DF_CrmCustomers_TeamKey DEFAULT '';
IF COL_LENGTH('CrmLeads','TeamKey') IS NULL ALTER TABLE [CrmLeads] ADD [TeamKey] nvarchar(80) NOT NULL CONSTRAINT DF_CrmLeads_TeamKey DEFAULT '';
IF COL_LENGTH('CrmDeals','TeamKey') IS NULL ALTER TABLE [CrmDeals] ADD [TeamKey] nvarchar(80) NOT NULL CONSTRAINT DF_CrmDeals_TeamKey DEFAULT '';
IF COL_LENGTH('CrmTasks','TeamKey') IS NULL ALTER TABLE [CrmTasks] ADD [TeamKey] nvarchar(80) NOT NULL CONSTRAINT DF_CrmTasks_TeamKey DEFAULT '';
