IF OBJECT_ID(N'[CrmTeamMembers]', N'U') IS NULL CREATE TABLE [CrmTeamMembers]([Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY,[TeamId] int NOT NULL,[UserName] nvarchar(180) NOT NULL,[AccessScope] nvarchar(20) NOT NULL,[IsPrimary] bit NOT NULL,[CreatedAtUtc] datetime2 NOT NULL,[UpdatedAtUtc] datetime2 NOT NULL,[IsDeleted] bit NOT NULL,[CreatedBy] nvarchar(max) NULL,[UpdatedBy] nvarchar(max) NULL);
IF OBJECT_ID(N'[CrmLoginAudits]', N'U') IS NULL CREATE TABLE [CrmLoginAudits]([Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY,[UserName] nvarchar(180) NOT NULL,[IpAddress] nvarchar(64) NOT NULL,[UserAgent] nvarchar(500) NOT NULL,[Succeeded] bit NOT NULL,[Result] nvarchar(120) NOT NULL,[CreatedAtUtc] datetime2 NOT NULL,[UpdatedAtUtc] datetime2 NOT NULL,[IsDeleted] bit NOT NULL,[CreatedBy] nvarchar(max) NULL,[UpdatedBy] nvarchar(max) NULL);
IF OBJECT_ID(N'[CrmLeadRoutingRules]', N'U') IS NULL CREATE TABLE [CrmLeadRoutingRules]([Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY,[Name] nvarchar(120) NOT NULL,[Source] nvarchar(80) NOT NULL,[MinScore] int NOT NULL,[AssignTo] nvarchar(180) NOT NULL,[TeamKey] nvarchar(80) NOT NULL,[Priority] int NOT NULL,[IsActive] bit NOT NULL,[CreatedAtUtc] datetime2 NOT NULL,[UpdatedAtUtc] datetime2 NOT NULL,[IsDeleted] bit NOT NULL,[CreatedBy] nvarchar(max) NULL,[UpdatedBy] nvarchar(max) NULL);
IF OBJECT_ID(N'[CrmActivities]', N'U') IS NULL CREATE TABLE [CrmActivities]([Id] int IDENTITY(1,1) NOT NULL PRIMARY KEY,[EntityType] nvarchar(40) NOT NULL,[EntityId] int NOT NULL,[Type] nvarchar(80) NOT NULL,[Subject] nvarchar(240) NOT NULL,[Detail] nvarchar(2000) NOT NULL,[Owner] nvarchar(160) NOT NULL,[OccurredAtUtc] datetime2 NOT NULL,[CreatedAtUtc] datetime2 NOT NULL,[UpdatedAtUtc] datetime2 NOT NULL,[IsDeleted] bit NOT NULL,[CreatedBy] nvarchar(max) NULL,[UpdatedBy] nvarchar(max) NULL);
""");
  if(!await db.CrmCustomers.AnyAsync()){ db.CrmCustomers.AddRange(
   new CustomerEntity{Name="الهام شریفی",Company="فناوری سپهر",Email="elham@sepehr.ir",Phone="021-88771231",Segment="Enterprise",Owner="sales@ashkancrm.local",Status="Active",Score=94,CreatedBy="Seed"},
   new CustomerEntity{Name="فرهاد احمدی",Company="راهکار نوین",Email="farhad@novin.ir",Phone="021-44559121",Segment="SMB",Owner="sales@ashkancrm.local",Status="Active",Score=82,CreatedBy="Seed"}); }
  if(!await db.CrmLeads.AnyAsync()) db.CrmLeads.AddRange(new LeadEntity{Name="پویان مرادی",Company="داده گستر",Source="LinkedIn",Owner="sales@ashkancrm.local",Status="Qualified",Score=91,LastContact="Today",CreatedBy="Seed"},new LeadEntity{Name="شیوا رضایی",Company="آریا وب",Source="Website",Owner="sales@ashkancrm.local",Status="New",Score=72,LastContact="Yesterday",CreatedBy="Seed"});
  if(!await db.CrmDeals.AnyAsync()) db.CrmDeals.AddRange(new DealEntity{Title="Enterprise CRM Renewal",Customer="فناوری سپهر",Owner="sales@ashkancrm.local",Value=1850000000,Stage="Proposal",Probability=75,CloseDate="1405/08/20",CreatedBy="Seed"},new DealEntity{Title="Support Gold",Customer="راهکار نوین",Owner="sales@ashkancrm.local",Value=420000000,Stage="Negotiation",Probability=60,CloseDate="1405/08/28",CreatedBy="Seed"});
  if(!await db.CrmTasks.AnyAsync()) db.CrmTasks.AddRange(
   new CrmTaskEntity{Title="Follow up enterprise renewal",Type="FollowUp",Assignee="sales@ashkancrm.local",Priority="High",Status="Open",DueAtUtc=DateTime.UtcNow.AddHours(5),ReminderAtUtc=DateTime.UtcNow.AddHours(4),RelatedEntityType="Deal",RelatedEntityId=1,CreatedBy="Seed"},
   new CrmTaskEntity{Title="Prepare discovery call",Type="Call",Assignee="sales@ashkancrm.local",Priority="Medium",Status="Open",DueAtUtc=DateTime.UtcNow.AddDays(1),CreatedBy="Seed"});
  if(!await db.CrmSalesTargets.AnyAsync()) db.CrmSalesTargets.Add(new SalesTargetEntity{Owner="sales@ashkancrm.local",Year=DateTime.UtcNow.Year,Month=DateTime.UtcNow.Month,TargetAmount=2500000000m,StretchAmount=3000000000m,CreatedBy="Seed"});
  await db.SaveChangesAsync();
  if(!await db.CrmLeadRoutingRules.AnyAsync()) { db.CrmLeadRoutingRules.Add(new LeadRoutingRuleEntity{Name="High score web leads",Source="Website",MinScore=80,AssignTo="sales@ashkancrm.local",TeamKey="sales-core",Priority=10,CreatedBy="Seed"}); await db.SaveChangesAsync(); }
  if(!await db.CrmTeams.AnyAsync()){ var team=new CrmTeamEntity{TeamKey="sales-core",Name="Core Sales",Department="Sales",ManagerUserName="sales@ashkancrm.local",CreatedBy="Seed"}; db.CrmTeams.Add(team); await db.SaveChangesAsync(); db.CrmTeamMembers.AddRange(new CrmTeamMemberEntity{TeamId=team.Id,UserName="sales@ashkancrm.local",AccessScope="Team",CreatedBy="Seed"},new CrmTeamMemberEntity{TeamId=team.Id,UserName="salesrep@ashkancrm.local",AccessScope="Own",CreatedBy="Seed"}); await db.SaveChangesAsync(); await db.Database.ExecuteSqlRawAsync("UPDATE CrmCustomers SET TeamKey='sales-core' WHERE TeamKey=''; UPDATE CrmLeads SET TeamKey='sales-core' WHERE TeamKey=''; UPDATE CrmDeals SET TeamKey='sales-core' WHERE TeamKey=''; UPDATE CrmTasks SET TeamKey='sales-core' WHERE TeamKey='';"); }
